<?php
declare(strict_types=1);
require_once __DIR__.'/nz-moderation.php';

function nzs_attr(array $p,array $names):string{foreach((array)($p['attributes']??[]) as $k=>$v)if(in_array((string)$k,$names,true))return trim((string)$v);return'';}
function nzs_num(string $v):int{return(int)preg_replace('/\D+/u','',$v);}
function nzs_distance(float $a1,float $o1,float $a2,float $o2):float{$r=6371;$dA=deg2rad($a2-$a1);$dO=deg2rad($o2-$o1);$x=sin($dA/2)**2+cos(deg2rad($a1))*cos(deg2rad($a2))*sin($dO/2)**2;return$r*2*atan2(sqrt($x),sqrt(1-$x));}
function nzs_params():array{$keys=['q','category','subcategory','province','city','district','price_min','price_max','brand','model','year_min','year_max','mileage_max','area_min','area_max','rooms','sort','radius','lat','lng'];$out=[];foreach($keys as $k){$v=trim((string)($_GET[$k]??''));if($v!=='')$out[$k]=mb_substr($v,0,120);}return$out;}
function nzs_active():bool{$page=(string)($_GET['page']??'home');if($page==='search')return true;foreach(['q','category','subcategory','province','city','district','price_min','price_max','brand','model','year_min','year_max','mileage_max','area_min','area_max','rooms','sort','radius'] as $k)if(isset($_GET[$k])&&trim((string)$_GET[$k])!=='')return true;return false;}
function nzs_filter(array $posts,array $f):array{
    $out=[];$lat=isset($f['lat'])&&is_numeric($f['lat'])?(float)$f['lat']:null;$lng=isset($f['lng'])&&is_numeric($f['lng'])?(float)$f['lng']:null;$radius=isset($f['radius'])&&is_numeric($f['radius'])?(float)$f['radius']:null;
    foreach($posts as $p){if(($p['status']??'')!=='published')continue;$blob=nzm_normalize((string)($p['title']??'').' '.(string)($p['description']??'').' '.implode(' ',array_map('strval',(array)($p['attributes']??[]))));
        if(!empty($f['q'])&&mb_stripos($blob,nzm_normalize($f['q']),0,'UTF-8')===false)continue;
        foreach(['category','subcategory','province','city','district'] as $k)if(!empty($f[$k])&&($p[$k]??'')!==$f[$k])continue 2;
        $price=(int)($p['price']??0);if(isset($f['price_min'])&&$price<(int)$f['price_min'])continue;if(isset($f['price_max'])&&(int)$f['price_max']>0&&$price>(int)$f['price_max'])continue;
        $brand=nzs_attr($p,['برند','برند/سازنده']);$model=nzs_attr($p,['مدل']);if(!empty($f['brand'])&&mb_stripos(nzm_normalize($brand),nzm_normalize($f['brand']),0,'UTF-8')===false)continue;if(!empty($f['model'])&&mb_stripos(nzm_normalize($model),nzm_normalize($f['model']),0,'UTF-8')===false)continue;
        $year=nzs_num(nzs_attr($p,['سال ساخت','سال تولید']));if(isset($f['year_min'])&&$year>0&&$year<(int)$f['year_min'])continue;if(isset($f['year_max'])&&$year>0&&$year>(int)$f['year_max'])continue;
        $mileage=nzs_num(nzs_attr($p,['کارکرد']));if(isset($f['mileage_max'])&&$mileage>(int)$f['mileage_max'])continue;
        $area=nzs_num(nzs_attr($p,['متراژ']));if(isset($f['area_min'])&&$area>0&&$area<(int)$f['area_min'])continue;if(isset($f['area_max'])&&$area>0&&$area>(int)$f['area_max'])continue;
        if(!empty($f['rooms'])&&nzs_attr($p,['تعداد اتاق'])!==$f['rooms'])continue;
        if($radius!==null&&$lat!==null&&$lng!==null&&isset($p['latitude'],$p['longitude'])){if(nzs_distance($lat,$lng,(float)$p['latitude'],(float)$p['longitude'])>$radius)continue;}
        $p['_nzs_promo']=function_exists('nzl_promo_priority')?nzl_promo_priority($p):0;$p['_nzs_rand']=random_int(1,PHP_INT_MAX);$out[]=$p;
    }
    $sort=$f['sort']??'new';usort($out,function($a,$b)use($sort,$lat,$lng){$pa=(int)($a['_nzs_promo']??0);$pb=(int)($b['_nzs_promo']??0);if($pa!==$pb)return$pb<=>$pa;if($pa>0){$ra=(int)($a['_nzs_rand']??0);$rb=(int)($b['_nzs_rand']??0);if($ra!==$rb)return$ra<=>$rb;}if($sort==='price_asc')return(int)($a['price']??0)<=>(int)($b['price']??0);if($sort==='price_desc')return(int)($b['price']??0)<=>(int)($a['price']??0);if($sort==='near'&&$lat!==null&&$lng!==null){$da=isset($a['latitude'],$a['longitude'])?nzs_distance($lat,$lng,(float)$a['latitude'],(float)$a['longitude']):PHP_FLOAT_MAX;$db=isset($b['latitude'],$b['longitude'])?nzs_distance($lat,$lng,(float)$b['latitude'],(float)$b['longitude']):PHP_FLOAT_MAX;return$da<=>$db;}return strtotime($b['created_at']??'now')<=>strtotime($a['created_at']??'now');});foreach($out as&$p){unset($p['_nzs_promo'],$p['_nzs_rand']);}unset($p);return$out;
}
function nzs_categories():array{return['املاک','وسایل نقلیه','کالای دیجیتال','خانه و آشپزخانه','خدمات','استخدام و کاریابی','شخصی','سرگرمی و فراغت','تجهیزات و صنعتی','کسب‌وکار و عمده‌فروشی','کشاورزی، حیوانات و مواد غذایی','آموزشی و اجتماعی'];}
function nzs_money(int $n):string{return$n>0?number_format($n).' تومان':'توافقی';}
function nzs_img(array $p):string{return!empty($p['images'][0])?'/marketplace-uploads/'.rawurlencode(basename((string)$p['images'][0])):'/niazestan-icon.svg';}
function nzs_render(array $db,?array $user):string{$f=nzs_params();$rows=nzs_filter($db['posts'],$f);$csrf=nzc_e($_SESSION['csrf']??'');$html='<main class="main"><div class="section-head"><div><h1>جستجوی آگهی‌ها</h1><p>'.count($rows).' نتیجه</p></div><a class="btn ghost" href="/nz">پاک کردن فیلترها</a></div><div class="content-grid"><form method="get" class="filter-card" style="display:block;position:static"><input type="hidden" name="page" value="search"><h3>فیلترها</h3>';
    $fields=[['q','جستجو','text'],['city','شهر','text'],['district','محله','text'],['price_min','حداقل قیمت','number'],['price_max','حداکثر قیمت','number'],['brand','برند','text'],['model','مدل','text'],['year_min','سال از','number'],['year_max','سال تا','number'],['mileage_max','حداکثر کارکرد','number'],['area_min','متراژ از','number'],['area_max','متراژ تا','number']];
    $html.='<div class="field"><label>دسته</label><select name="category"><option value="">همه دسته‌ها</option>';foreach(nzs_categories() as $c)$html.='<option '.(($f['category']??'')===$c?'selected':'').'>'.nzc_e($c).'</option>';$html.='</select></div>';
    foreach($fields as[$name,$label,$type])$html.='<div class="field"><label>'.$label.'</label><input type="'.$type.'" name="'.$name.'" value="'.nzc_e($f[$name]??'').'"'.($name==='year_min'||$name==='year_max'?' min="1300" max="1405"':'').'></div>';
    $html.='<div class="field"><label>مرتب‌سازی</label><select name="sort">';foreach(['new'=>'جدیدترین','price_asc'=>'ارزان‌ترین','price_desc'=>'گران‌ترین','near'=>'نزدیک‌ترین'] as$k=>$v)$html.='<option value="'.$k.'" '.(($f['sort']??'new')===$k?'selected':'').'>'.$v.'</option>';$html.='</select></div><input type="hidden" name="lat" id="nzsLat" value="'.nzc_e($f['lat']??'').'"><input type="hidden" name="lng" id="nzsLng" value="'.nzc_e($f['lng']??'').'"><div class="field"><label>شعاع اطراف من (کیلومتر)</label><select name="radius"><option value="">بدون محدودیت</option>';foreach([1,5,10,30,50]as$r)$html.='<option '.(($f['radius']??'')===(string)$r?'selected':'').' value="'.$r.'">'.$r.' کیلومتر</option>';$html.='</select></div><button type="button" class="btn ghost" style="width:100%;margin-bottom:8px" onclick="navigator.geolocation&&navigator.geolocation.getCurrentPosition(p=>{nzsLat.value=p.coords.latitude;nzsLng.value=p.coords.longitude})">موقعیت فعلی من</button><button class="btn primary" style="width:100%">اعمال فیلتر</button></form><section><form method="get" class="mobile-search" style="display:flex;margin-bottom:10px"><input type="hidden" name="page" value="search"><span class="mobile-search-icon"></span><input name="q" value="'.nzc_e($f['q']??'').'" placeholder="جستجو در نیازستان"></form>';
    if($user&&$f){$query=http_build_query($f);$html.='<form method="post" style="margin-bottom:10px"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="save_search"><input type="hidden" name="query" value="'.nzc_e($query).'"><button class="btn ghost">☆ ذخیره این جستجو</button></form>';}
    $html.='<div class="listings">';if(!$rows)$html.='<div class="empty">آگهی مطابق این فیلتر پیدا نشد.</div>';foreach($rows as$p){$badges=function_exists('nzl_promo_badges')?nzl_promo_badges($p):'';$html.='<a class="listing" href="/nz?id='.rawurlencode((string)$p['id']).'"><div class="listing-media"><img loading="lazy" src="'.nzc_e(nzs_img($p)).'" alt="'.nzc_e($p['title']??'').'"></div><div class="listing-body">'.($badges!==''?'<div style="margin-bottom:5px">'.$badges.'</div>':'').'<div class="listing-title">'.nzc_e($p['title']??'آگهی').'</div><div class="listing-price">'.nzc_e(nzs_money((int)($p['price']??0))).'</div><div class="listing-meta"><span>'.nzc_e(($p['city']??'').(!empty($p['district'])?'، '.$p['district']:'')).'</span></div></div></a>';}$html.='</div></section></div></main>';return$html;}
function nzs_saved_html(array$db,array$user):string{$rows=array_values(array_filter($db['saved_searches']??[],fn($s)=>($s['user_id']??'')===$user['id']));$csrf=nzc_e($_SESSION['csrf']??'');$h='<main class="page page-narrow"><div class="surface"><h1>جستجوهای ذخیره‌شده</h1><div class="menu-list">';if(!$rows)$h.='<div class="empty">هنوز جستجویی ذخیره نکرده‌اید.</div>';foreach(array_reverse($rows)as$s){$q=(string)($s['query']??'');$h.='<div class="menu-item"><a style="text-decoration:none;flex:1" href="/nz?page=search&'.nzc_e($q).'"><b>'.nzc_e($s['label']??'جستجوی ذخیره‌شده').'</b></a><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="delete_saved_search"><input type="hidden" name="search_id" value="'.nzc_e($s['id']??'').'"><button class="btn danger">حذف</button></form></div>';}$h.='</div></div></main>';return$h;}
function nzs_handle_post(string$action):never{nzc_session_open();$db=nzc_db_read();$u=nzc_require_user($db);if(!nzc_csrf_valid())throw new RuntimeException('درخواست نامعتبر است.');if($action==='save_search'){$query=mb_substr(trim((string)($_POST['query']??'')),0,1200);parse_str($query,$tmp);$label=trim((string)($tmp['q']??''));if($label==='')$label=trim((string)($tmp['category']??'جستجوی ذخیره‌شده'));nzc_db_write(function(&$db)use($u,$query,$label){$db['saved_searches'][]=['id'=>nzc_uid('s'),'user_id'=>$u['id'],'query'=>$query,'label'=>mb_substr($label,0,80),'created_at'=>nzc_now()];});nzc_flash('جستجو ذخیره شد.');nzc_redirect('/nz?page=saved-searches');}if($action==='delete_saved_search'){$id=(string)($_POST['search_id']??'');nzc_db_write(function(&$db)use($u,$id){$db['saved_searches']=array_values(array_filter($db['saved_searches']??[],fn($s)=>(($s['id']??'')!==$id)||(($s['user_id']??'')!==$u['id'])));});nzc_redirect('/nz?page=saved-searches');}throw new RuntimeException('درخواست نامعتبر است.');}
function nzs_enhance(string$html):string{nzc_session_open();$db=nzc_db_read();$user=nzc_current_user($db);$page=(string)($_GET['page']??'home');if($page==='saved-searches'&&$user)return nzd_replace_main($html,nzs_saved_html($db,$user));if(nzs_active())return nzd_replace_main($html,nzs_render($db,$user));if($page==='profile'&&$user)$html=str_replace('</div><form method="post" style="margin-top:18px">','<a class="menu-item" href="/nz?page=saved-searches"><span>جستجوهای ذخیره‌شده</span><span>‹</span></a></div><form method="post" style="margin-top:18px">',$html);return$html;}
